import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"垃圾回收","description":"","frontmatter":{},"headers":[],"relativePath":"go/basic/advanced/gc.md","filePath":"go/basic/advanced/gc.md"}`),a={name:`go/basic/advanced/gc.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="垃圾回收" tabindex="-1">垃圾回收 <a class="header-anchor" href="#垃圾回收" aria-label="Permalink to “垃圾回收”">​</a></h1><p>GC：Garbage Collection，垃圾回收。</p><h2 id="一些名词" tabindex="-1">一些名词 <a class="header-anchor" href="#一些名词" aria-label="Permalink to “一些名词”">​</a></h2><h3 id="垃圾内存" tabindex="-1">垃圾内存 <a class="header-anchor" href="#垃圾内存" aria-label="Permalink to “垃圾内存”">​</a></h3><p>程序中不再被引用的对象（即 “垃圾”），释放其占用的内存，供新对象使用。</p><h3 id="内存泄漏" tabindex="-1">内存泄漏 <a class="header-anchor" href="#内存泄漏" aria-label="Permalink to “内存泄漏”">​</a></h3><p>程序在分配了内存但不再需要使用时，却未能正确释放这块内存空间，导致这部分内存被占用且无法再次使用，从而造成系统内存的浪费和性能下降。 这种问题会随着程序运行积累，最终可能导致程序甚至整个系统崩溃。</p><h3 id="内存溢出" tabindex="-1">内存溢出 <a class="header-anchor" href="#内存溢出" aria-label="Permalink to “内存溢出”">​</a></h3><p>程序在申请内存时，无法满足当前需求，导致内存分配失败。</p><h2 id="三色标记法" tabindex="-1">三色标记法 <a class="header-anchor" href="#三色标记法" aria-label="Permalink to “三色标记法”">​</a></h2><p><code>go gc</code>主要算法是三色标记法（Tri-color Marking），通过将对象分为三种颜色来跟踪其状态：</p><ul><li>白色：未扫描的对象（最终会回收）</li><li>灰色：已扫描但其引用的对象未扫描（处理中）</li><li>黑色：已扫描且其引用的对象均已扫描（存活）</li></ul><h2 id="gc-的原理" tabindex="-1">GC 的原理 <a class="header-anchor" href="#gc-的原理" aria-label="Permalink to “GC 的原理”">​</a></h2><h3 id="标记准备-stw-微秒级" tabindex="-1">标记准备（STW，微秒级） <a class="header-anchor" href="#标记准备-stw-微秒级" aria-label="Permalink to “标记准备（STW，微秒级）”">​</a></h3><ul><li>全局<code>STW</code>，所有用户<code>G</code>停止运行，防止内存对象状态突变。</li><li>扫描所有根对象，将直接可达的对象标记为灰色，加入 “灰色队列”（待处理队列）。</li><li><code>STW</code> 结束，恢复所有业务 <code>P/M/G</code> 运行。</li><li>目的: 初始化标记环境、产出第一批灰色对象。</li></ul><h3 id="并发标记" tabindex="-1">并发标记 <a class="header-anchor" href="#并发标记" aria-label="Permalink to “并发标记”">​</a></h3><ul><li><code>GC</code>协程和业务协程同时运行</li><li>从灰色队列中取出一个灰色对象，将其标记为黑色。</li><li>遍历该黑色对象引用的所有子对象： <ul><li>如果子对象是白色，将其标记为灰色，并加入灰色队列。</li><li>如果子对象是灰色，忽略。</li><li>如果子对象是黑色，忽略。</li><li>循环直到灰色队列为空（初步标记完成）。理论可以全部标记为黑色。</li></ul></li></ul><h3 id="标记终止-stw" tabindex="-1">标记终止（STW） <a class="header-anchor" href="#标记终止-stw" aria-label="Permalink to “标记终止（STW）”">​</a></h3><p>并发标记灰色队列为空后，进入该阶段。</p><ul><li>暂停所有业务协程。</li><li>并发阶段栈上指针可能被业务代码修改，必须重新扫描根，补全遗漏标记。</li><li>处理残留灰色对象，彻底遍历，保证所有存活对象全部标黑。</li><li>关闭写屏障。</li><li>统计标记结果：区分存活对象（黑）、死亡对象（白）。</li><li><code>STW</code>结束，恢复业务。</li><li>收尾标记，保证 100% 标记准确，杜绝并发期间的标记遗漏。</li></ul><h3 id="并发清扫" tabindex="-1">并发清扫 <a class="header-anchor" href="#并发清扫" aria-label="Permalink to “并发清扫”">​</a></h3><p>标记完成后，开始回收死亡对象，全程并发。</p><ul><li>逐个判断对象颜色： <ul><li>黑色：存活，保留，颜色暂时不变</li><li>白色：已死亡，回收内存，将内存放回堆空闲链表</li></ul></li></ul><h3 id="并发重置" tabindex="-1">并发重置 <a class="header-anchor" href="#并发重置" aria-label="Permalink to “并发重置”">​</a></h3><p>清扫完成后执行，为下一轮<code>GC</code>重置状态。</p><ul><li>把本轮标记为黑色的存活对象，全部重新置为白色。</li><li>清空灰色队列、标记相关状态、计数器。</li><li>重置 <code>GC</code>阈值、辅助 <code>GC</code> 标记状态。</li><li>本轮 <code>GC</code>正式结束，等待下一次内存阈值触发。</li></ul>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};